class Icons:
    def __init__(self, root):
        self.root, self.cache = root, {}

    def get(self, name, color, size):
        key = (name, color, size)
        if key not in self.cache:
            import pymupdf
            svg = _SVGS[name].replace('#212121', color)
            with pymupdf.open(stream=svg.encode(), filetype='svg') as document:
                pix = document[0].get_pixmap(matrix=pymupdf.Matrix(size/20, size/20), alpha=True)
                self.cache[key] = tk.PhotoImage(master=self.root, data=pix.tobytes('png'))
        return self.cache[key]
